/**
 * Heartbeat CMS - Self-Contained Alpine.js Micro-Runtime (Zero-Dependency)
 * Implements reactive x-data, x-show, x-model, @click / x-on, x-text, :class, :disabled, :style, <template x-if>, <template x-for>
 */
(function () {
    'use strict';

    function initAlpine() {
        const rootElements = document.querySelectorAll('[x-data]');
        rootElements.forEach(root => {
            const dataExpr = root.getAttribute('x-data');
            let state;
            try {
                const fn = new Function('return (' + dataExpr + ')');
                state = fn();
            } catch (e) {
                console.error('[Heartbeat UI] Failed to evaluate x-data:', e);
                return;
            }

            const listeners = new Set();
            function notify() {
                listeners.forEach(fn => fn());
            }

            function makeReactive(obj) {
                if (typeof obj !== 'object' || obj === null) return obj;
                for (const key in obj) {
                    if (typeof obj[key] === 'object' && obj[key] !== null) {
                        obj[key] = makeReactive(obj[key]);
                    }
                }
                return new Proxy(obj, {
                    set(target, prop, value) {
                        if (typeof value === 'object' && value !== null) {
                            value = makeReactive(value);
                        }
                        target[prop] = value;
                        notify();
                        return true;
                    }
                });
            }

            const proxy = makeReactive(state);

            function evalInContext(expr) {
                try {
                    const fn = new Function(...Object.keys(proxy), 'return (' + expr + ');');
                    return fn(...Object.values(proxy));
                } catch (e) {
                    return undefined;
                }
            }

            function execInContext(stmt, event) {
                try {
                    const keys = [...Object.keys(proxy), '$event'];
                    const vals = [...Object.values(proxy), event];
                    const fn = new Function(...keys, stmt);
                    return fn(...vals);
                } catch (e) {
                    console.error('[Heartbeat UI] Action error:', stmt, e);
                }
            }

            function bindElement(el) {
                // Event bindings: @click, @input, x-on:*
                Array.from(el.attributes || []).forEach(attr => {
                    const name = attr.name;
                    const val = attr.value;

                    if (name.startsWith('@') || name.startsWith('x-on:')) {
                        const eventName = name.startsWith('@') ? name.substring(1) : name.substring(5);
                        el.addEventListener(eventName, (e) => {
                            execInContext(val, e);
                            notify();
                        });
                    }
                });

                // Two-way binding: x-model
                if (el.hasAttribute('x-model')) {
                    const modelExpr = el.getAttribute('x-model');
                    if (el.type === 'radio') {
                        el.addEventListener('change', () => {
                            if (el.checked) {
                                execInContext(modelExpr + ' = ' + JSON.stringify(el.value));
                                notify();
                            }
                        });
                        listeners.add(() => {
                            const current = evalInContext(modelExpr);
                            el.checked = (current === el.value);
                        });
                    } else if (el.type === 'checkbox') {
                        el.addEventListener('change', () => {
                            execInContext(modelExpr + ' = ' + el.checked);
                            notify();
                        });
                        listeners.add(() => {
                            el.checked = !!evalInContext(modelExpr);
                        });
                    } else {
                        el.addEventListener('input', () => {
                            const val = el.type === 'number' ? Number(el.value) : el.value;
                            execInContext(modelExpr + ' = ' + JSON.stringify(val));
                            notify();
                        });
                        listeners.add(() => {
                            const current = evalInContext(modelExpr);
                            if (current !== undefined && el.value !== String(current)) {
                                el.value = current;
                            }
                        });
                    }
                }

                // Conditional visibility: x-show
                if (el.hasAttribute('x-show')) {
                    const showExpr = el.getAttribute('x-show');
                    listeners.add(() => {
                        const visible = !!evalInContext(showExpr);
                        el.style.display = visible ? '' : 'none';
                    });
                }

                // Text interpolation: x-text
                if (el.hasAttribute('x-text')) {
                    const textExpr = el.getAttribute('x-text');
                    listeners.add(() => {
                        const res = evalInContext(textExpr);
                        el.textContent = res !== undefined ? res : '';
                    });
                }

                // Attribute binding: :disabled, x-bind:disabled
                if (el.hasAttribute(':disabled') || el.hasAttribute('x-bind:disabled')) {
                    const expr = el.getAttribute(':disabled') || el.getAttribute('x-bind:disabled');
                    listeners.add(() => {
                        el.disabled = !!evalInContext(expr);
                    });
                }

                // Style binding: :style, x-bind:style
                if (el.hasAttribute(':style') || el.hasAttribute('x-bind:style')) {
                    const expr = el.getAttribute(':style') || el.getAttribute('x-bind:style');
                    listeners.add(() => {
                        const styleVal = evalInContext(expr);
                        if (typeof styleVal === 'string') {
                            el.style.cssText += styleVal;
                        }
                    });
                }

                // Class binding: :class, x-bind:class
                if (el.hasAttribute(':class') || el.hasAttribute('x-bind:class')) {
                    const expr = el.getAttribute(':class') || el.getAttribute('x-bind:class');
                    const initialClass = el.dataset.initialClass || el.getAttribute('class') || '';
                    el.dataset.initialClass = initialClass;

                    listeners.add(() => {
                        const classResult = evalInContext(expr);
                        let finalClass = initialClass;
                        if (typeof classResult === 'string') {
                            finalClass += ' ' + classResult;
                        } else if (Array.isArray(classResult)) {
                            finalClass += ' ' + classResult.join(' ');
                        } else if (typeof classResult === 'object' && classResult !== null) {
                            for (const c in classResult) {
                                if (classResult[c]) finalClass += ' ' + c;
                            }
                        }
                        el.className = finalClass.trim();
                    });
                }

                // Templates: <template x-if="...">
                if (el.tagName === 'TEMPLATE' && el.hasAttribute('x-if')) {
                    const ifExpr = el.getAttribute('x-if');
                    let renderedNode = null;

                    listeners.add(() => {
                        const condition = !!evalInContext(ifExpr);
                        if (condition && !renderedNode) {
                            const clone = el.content.cloneNode(true);
                            renderedNode = clone.firstElementChild;
                            if (renderedNode) {
                                el.parentNode.insertBefore(renderedNode, el.nextSibling);
                                bindSubtree(renderedNode);
                            }
                        } else if (!condition && renderedNode) {
                            renderedNode.remove();
                            renderedNode = null;
                        }
                    });
                }

                // Templates: <template x-for="(item, key) in items">
                if (el.tagName === 'TEMPLATE' && el.hasAttribute('x-for')) {
                    const forExpr = el.getAttribute('x-for');
                    const match = forExpr.match(/^\s*(?:\(([^,]+),\s*([^)]+)\)|([^\s]+))\s+in\s+([^\s]+)\s*$/);
                    if (match) {
                        const itemVar = match[1] || match[3];
                        const keyVar = match[2];
                        const collectionExpr = match[4];
                        let renderedNodes = [];

                        listeners.add(() => {
                            renderedNodes.forEach(n => n.remove());
                            renderedNodes = [];

                            const collection = evalInContext(collectionExpr);
                            if (typeof collection === 'object' && collection !== null) {
                                Object.entries(collection).forEach(([k, item]) => {
                                    const clone = el.content.cloneNode(true);
                                    const node = clone.firstElementChild;
                                    if (node) {
                                        el.parentNode.insertBefore(node, el);
                                        renderedNodes.push(node);

                                        // Local context for repeater element
                                        const subContext = Object.create(proxy);
                                        subContext[itemVar.trim()] = item;
                                        if (keyVar) subContext[keyVar.trim()] = k;

                                        // Bind subtree with subcontext
                                        bindWithContext(node, subContext);
                                    }
                                });
                            }
                        });
                    }
                }
            }

            function bindWithContext(node, context) {
                // Evaluates and updates node using custom context
                if (node.hasAttribute && node.hasAttribute('x-text')) {
                    const expr = node.getAttribute('x-text');
                    try {
                        const fn = new Function(...Object.keys(context), 'return (' + expr + ');');
                        node.textContent = fn(...Object.values(context));
                    } catch (e) {}
                }
                if (node.hasAttribute && (node.hasAttribute(':class') || node.hasAttribute('x-bind:class'))) {
                    const expr = node.getAttribute(':class') || node.getAttribute('x-bind:class');
                    const initialClass = node.getAttribute('class') || '';
                    try {
                        const fn = new Function(...Object.keys(context), 'return (' + expr + ');');
                        const res = fn(...Object.values(context));
                        if (typeof res === 'string') node.className = (initialClass + ' ' + res).trim();
                    } catch (e) {}
                }
                Array.from(node.children || []).forEach(child => bindWithContext(child, context));
            }

            function bindSubtree(node) {
                bindElement(node);
                Array.from(node.children || []).forEach(child => bindSubtree(child));
            }

            // Initial binding of root element tree
            bindSubtree(root);

            // Initial render
            notify();
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAlpine);
    } else {
        initAlpine();
    }
})();

